import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import path from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const db = new DatabaseSync(dbPath);
db.exec('PRAGMA foreign_keys = ON');
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0,
  default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_priority IN ('Low','Normal','High'))
);
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low','Normal','High')),
  due_date TEXT,
  sort_order INTEGER
);`);

try { db.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
db.exec('UPDATE tasks SET sort_order = id WHERE sort_order IS NULL');

try { db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}

try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}

try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}

try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}

const indexHtml = await readFile(new URL('./public/index.html', import.meta.url));
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const send = (status, body, type = 'application/json; charset=utf-8') => {
    res.writeHead(status, { 'content-type': type, 'x-content-type-options': 'nosniff' });
    res.end(body);
  };

  if (url.pathname === '/health' && req.method === 'GET') {
    return send(200, JSON.stringify({ status: 'ok' }));
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
    return send(200, JSON.stringify(db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
      FROM projects p WHERE p.archived = ? ORDER BY p.id`).all(archived)));
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (archiveMatch && req.method === 'PATCH') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    try {
      const archived = JSON.parse(raw).archived ? 1 : 0;
      const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archived, archiveMatch[1]);
      return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    try {
      const name = String(JSON.parse(raw).name ?? '').trim();
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return send(201, JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    } catch {
      return send(400, JSON.stringify({ error: 'Invalid request' }));
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    const project = db.prepare('SELECT id FROM projects WHERE id = ?').get(tasksMatch[1]);
    if (!project) return send(404, JSON.stringify({ error: 'Not found' }));
    return send(200, JSON.stringify(db.prepare('SELECT id, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY sort_order, id').all(tasksMatch[1])));
  }
  if (tasksMatch && req.method === 'POST') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    try {
      const project = db.prepare('SELECT id, archived, default_priority FROM projects WHERE id = ?').get(tasksMatch[1]);
      if (!project) return send(404, JSON.stringify({ error: 'Not found' }));
      if (project.archived) return send(403, JSON.stringify({ error: 'Archived project' }));
      const title = String(JSON.parse(raw).title ?? '').trim();
      if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
      const result = db.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, COALESCE((SELECT MAX(sort_order) + 1 FROM tasks WHERE project_id = ?), 1))').run(tasksMatch[1], title, project.default_priority, tasksMatch[1]);
      return send(201, JSON.stringify({ id: Number(result.lastInsertRowid), title, completed: 0, priority: project.default_priority }));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    try {
      const payload = JSON.parse(raw);
      if (Object.hasOwn(payload, 'destinationProject')) {
        const destination = db.prepare('SELECT id FROM projects WHERE id = ? AND archived = 0').get(payload.destinationProject);
        const task = db.prepare('SELECT id FROM tasks WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)').get(taskMatch[1]);
        if (!destination || !task) return send(404, JSON.stringify({ error: 'Not found' }));
        const next = db.prepare('SELECT COALESCE(MAX(sort_order), 0) + 1 AS value FROM tasks WHERE project_id = ?').get(destination.id).value;
        db.prepare('UPDATE tasks SET project_id = ?, sort_order = ? WHERE id = ?').run(destination.id, next, taskMatch[1]);
        return send(200, JSON.stringify({ ok: true }));
      }
      if (Object.hasOwn(payload, 'dueDate')) {
        const rawDate = String(payload.dueDate ?? '').trim();
        let dueDate = null;
        if (rawDate) {
          const match = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
          if (!match) return send(400, JSON.stringify({ error: 'Due date must be a valid YYYY-MM-DD date' }));
          const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
          const date = new Date(0);
          date.setUTCHours(0, 0, 0, 0);
          date.setUTCFullYear(year, month - 1, day);
          if (year < 1 || date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return send(400, JSON.stringify({ error: 'Due date must be a valid YYYY-MM-DD date' }));
          dueDate = rawDate;
        }
        const result = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)').run(dueDate, taskMatch[1]);
        return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
      }
      if (Object.hasOwn(payload, 'priority')) {
        if (!['Low', 'Normal', 'High'].includes(payload.priority)) return send(400, JSON.stringify({ error: 'Invalid priority' }));
        const result = db.prepare(`UPDATE tasks SET priority = ? WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)`).run(payload.priority, taskMatch[1]);
        return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
      }
      if (Object.hasOwn(payload, 'title')) {
        const title = String(payload.title ?? '').trim();
        if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
        const result = db.prepare(`UPDATE tasks SET title = ? WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)`).run(title, taskMatch[1]);
        return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
      }
      const completed = payload.completed ? 1 : 0;
      const result = db.prepare(`UPDATE tasks SET completed = ? WHERE id = ? AND project_id IN (SELECT id FROM projects WHERE archived = 0)`).run(completed, taskMatch[1]);
      return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && req.method === 'PATCH') {
    let raw = '';
    for await (const chunk of req) raw += chunk;
    try {
      const payload = JSON.parse(raw);
      if (Object.hasOwn(payload, 'defaultPriority')) {
        if (!['Low', 'Normal', 'High'].includes(payload.defaultPriority)) return send(400, JSON.stringify({ error: 'Invalid priority' }));
        const result = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ? AND archived = 0').run(payload.defaultPriority, projectMatch[1]);
        return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
      }
      const name = String(payload.name ?? '').trim();
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const result = db.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0').run(name, projectMatch[1]);
      return result.changes ? send(200, JSON.stringify({ ok: true })) : send(404, JSON.stringify({ error: 'Not found' }));
    } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
  }
  if (projectMatch && req.method === 'GET') {
    const project = db.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(projectMatch[1]);
    return project ? send(200, JSON.stringify(project)) : send(404, JSON.stringify({ error: 'Not found' }));
  }
  if (url.pathname === '/' || url.pathname.startsWith('/projects/')) {
    return send(200, indexHtml, 'text/html; charset=utf-8');
  }
  return send(404, JSON.stringify({ error: 'Not found' }));
});
server.listen(port, '0.0.0.0');

